using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
using MC2Pack;
namespace Astera {
sealed partial class LibraryForm {
    internal static int AuditLibraryOrganization(string root){try{
        if(Directory.Exists(root))throw new IOException("Use a new audit folder");Directory.CreateDirectory(root);var checks=new List<string>();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
        var state=new Store(Path.Combine(root,"state"));state.Settings.AnimatedEffects=false;state.Settings.UseMinecraftSkin=false;state.Settings.CheckOnStart=false;var custom=new CustomGame{Name="Private fixture",Executable=Application.ExecutablePath};state.Settings.CustomGames.Add(custom);
        using(var form=new LibraryForm(state,new Channel(),true)){
            form.Location=new Point(-30000,-30000);form.Show();Application.DoEvents();form.ReloadGames(custom);string key="custom:"+custom.Id;
            state.Settings.FavoriteGames.Add(key);var folder=new LibraryFolder{Name="My games"};folder.Games.Add(key);state.Settings.LibraryFolders.Add(folder);state.Save();form.SelectLibraryFilter("favorites");AuditAssert(form.games.Items.Count==1&&form.CurrentCustom==custom,"Favorites selection failed");form.SelectLibraryFilter("folder:"+folder.Id);AuditAssert(form.games.Items.Count==1&&form.CurrentCustom==custom,"Folder membership failed");form.SelectLibraryFilter("astera");AuditAssert(form.games.Items.Count==3&&form.games.Items.Cast<LibraryEntry>().All(e=>e.Custom==null),"Astera filter leaked custom entries");checks.Add("Favorites, personal folders and Astera defaults filter independently using stable game identities");
            form.SelectLibraryFilter("all");form.ReloadGames(custom);state.Settings.HiddenGames.Add(key);state.Save();form.ReloadGames(null,true,true);AuditAssert(form.CurrentCustom!=custom&&!form.heroTitle.Text.Contains("Private"),"Hidden game stayed in the right pane");form.librarySearch.Text="Private";AuditAssert(form.games.Items.Count==0,"Hidden game leaked into search");form.SelectLibraryFilter("favorites");AuditAssert(form.games.Items.Count==0&&form.GameKind==-1&&form.heroTitle.Text=="Your library"&&form.notes.Text==""&&form.profileLabel.Text==""&&form.installationPath.Text==""&&!form.play.Enabled,"Empty filter leaked prior game details or actions");form.SelectLibraryFilter("hidden");AuditAssert(form.games.Items.Count==1&&form.CurrentCustom==custom,"Explicit Hidden view did not show hidden game");checks.Add("Hidden games stay out of normal search/favorites; empty views clear artwork, private text and actions");
            form.librarySearch.Clear();state.Settings.HiddenGames.Remove(key);form.SelectLibraryFilter("all");form.ReloadGames(custom);int launches=0;AuditAssert(form.TryLibraryDoubleLaunch(form.activeLibraryEntry,delegate{launches++;}),"Playable double-click rejected");AuditAssert(!form.TryLibraryDoubleLaunch(form.activeLibraryEntry,delegate{launches++;})&&launches==1,"Double-click dispatched twice");form.busy=true;form.lastDoubleLaunch=null;AuditAssert(!form.TryLibraryDoubleLaunch(form.activeLibraryEntry,delegate{launches++;}),"Busy operation launched");form.busy=false;form.GameKind=1;form.RefreshView();AuditAssert(!form.TryLibraryDoubleLaunch(form.activeLibraryEntry,delegate{launches++;}),"Unlinked app triggered setup via double-click");form.ReloadGames(custom);UiEffects.Enabled=true;form.CancelGameTransition();form.GameKind=3;AuditAssert(form.gameTransition==null,"Same selection reloaded its page");UiEffects.Enabled=false;checks.Add("Double-click launches a playable selection once, skips busy/setup states, and reselecting the game does not reload");
            var reread=new Store(state.Root);AuditAssert(reread.Settings.FavoriteGames.Contains(key)&&reread.Settings.LibraryFolders.Single().Games.Contains(key)&&reread.Settings.HiddenGames.Contains(key),"Saved collection metadata did not persist");AuditAssert(File.Exists(custom.Executable),"Collection operations changed the game file");checks.Add("Collection metadata survives restart and game files remain untouched");form.TopMost=true;form.Location=Screen.PrimaryScreen.WorkingArea.Location;form.playtimeLedger.Data.Seconds[key]=7380;form.RefreshView();form.BringToFront();form.Activate();form.Refresh();MotionAudit.Pump(400);form.CaptureVisibleUi(root,"library-playtime-wide");form.Size=new Size(1100,760);form.Refresh();MotionAudit.Pump(300);form.CaptureVisibleUi(root,"library-playtime-compact");form.Close();
        }
        var ledger=new PlaytimeLedger(null);var game=new CustomGame{Executable=Application.ExecutablePath};ledger.Request("one",game,0);var session=ledger.Active["one"];ledger.Observe(session,false,5);AuditAssert(ledger.Total("one")==0,"Pending launch counted");ledger.Observe(session,true,10);ledger.Observe(session,true,15);AuditAssert(ledger.Total("one")==5,"Confirmed process time missing");ledger.Observe(session,true,3600);AuditAssert(ledger.Total("one")==5,"Sleep gap inflated playtime");ledger.Observe(session,false,3605);AuditAssert(ledger.Active.Count==0,"Closed game stayed active");ledger.Observe(session,true,3610);AuditAssert(ledger.Total("one")==5,"Stale observation revived a closed session");checks.Add("Playtime counts confirmed running intervals, excludes pending launches/sleep gaps, and stops on process exit");
        ledger.Request("failed",game,0);ledger.Observe(ledger.Active["failed"],false,181);AuditAssert(!ledger.Active.ContainsKey("failed")&&ledger.Total("failed")==0,"Failed launch accrued time");ledger.Request("roblox-a",new CustomGame{Platform="roblox"},0);ledger.Request("roblox-b",new CustomGame{Platform="roblox"},1);AuditAssert(!ledger.Active.ContainsKey("roblox-a")&&ledger.Active.ContainsKey("roblox-b"),"Roblox experience counted twice");var restored=new PlaytimeLedger(Engine.Json.Deserialize<PlaytimeData>(Engine.Json.Serialize(ledger.Data)));AuditAssert(restored.Total("one")==5&&restored.Active.Count==0,"Restart inflated history or restored an unconfirmed session");AuditAssert(FormatPlaytime(3661)=="1 hr 1 min"&&FormatPlaytime(59)=="0 min","Playtime display incorrect");checks.Add("Failed launches add no time, Roblox keeps one experience estimate, and restart restores totals without offline backfill");
        using(var process=Process.Start(new ProcessStartInfo(Application.ExecutablePath,"--ftl-tool-probe"){UseShellExecute=false,CreateNoWindow=true})){AuditAssert(PlaytimeProbe.Running(game),"Real launched process was not detected");process.WaitForExit(5000);}checks.Add("The process probe recognizes a real isolated Astera worker; no game or platform client is launched");
        AuditAssert(new Preferences().TrackPlaytime&&!Engine.Json.Deserialize<Preferences>("{\"TrackPlaytime\":false}").TrackPlaytime,"Playtime opt-out lost");checks.Add("Local playtime tracking defaults on and a saved opt-out remains off");
        File.WriteAllText(Path.Combine(root,"result.json"),Engine.Json.Serialize(new{Passed=true,Checks=checks,GamesLaunched=false,LivePreferencesChanged=false}));return 0;
    }catch(Exception error){Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"failure.txt"),error.ToString());return 1;}}
}
}
